const CARD_W = 860;
const CARD_H = 640;
const COL_GAP = 40;
const ROW_GAP = 40;
const GRID_LEFT = (3840 - (4 * CARD_W + 3 * COL_GAP)) / 2;
const GRID_TOP = 210;

const THUMB_LAYOUT = [
  { x: GRID_LEFT + 0 * (CARD_W + COL_GAP), y: GRID_TOP + 0 * (CARD_H + ROW_GAP), rot: -1.2, delay: 0 },
  { x: GRID_LEFT + 1 * (CARD_W + COL_GAP), y: GRID_TOP + 0 * (CARD_H + ROW_GAP), rot: 0.8, delay: 5 },
  { x: GRID_LEFT + 2 * (CARD_W + COL_GAP), y: GRID_TOP + 0 * (CARD_H + ROW_GAP), rot: -0.6, delay: 10 },
  { x: GRID_LEFT + 3 * (CARD_W + COL_GAP), y: GRID_TOP + 0 * (CARD_H + ROW_GAP), rot: 1.4, delay: 3 },
  { x: GRID_LEFT + 0 * (CARD_W + COL_GAP), y: GRID_TOP + 1 * (CARD_H + ROW_GAP), rot: 1.0, delay: 8 },
  { x: GRID_LEFT + 1 * (CARD_W + COL_GAP), y: GRID_TOP + 1 * (CARD_H + ROW_GAP), rot: -1.5, delay: 13 },
  { x: GRID_LEFT + 2 * (CARD_W + COL_GAP), y: GRID_TOP + 1 * (CARD_H + ROW_GAP), rot: 0.5, delay: 2 },
  { x: GRID_LEFT + 3 * (CARD_W + COL_GAP), y: GRID_TOP + 1 * (CARD_H + ROW_GAP), rot: -0.9, delay: 7 },
  { x: GRID_LEFT + 0 * (CARD_W + COL_GAP), y: GRID_TOP + 2 * (CARD_H + ROW_GAP), rot: -1.1, delay: 15 },
  { x: GRID_LEFT + 1 * (CARD_W + COL_GAP), y: GRID_TOP + 2 * (CARD_H + ROW_GAP), rot: 1.3, delay: 6 },
  { x: GRID_LEFT + 2 * (CARD_W + COL_GAP), y: GRID_TOP + 2 * (CARD_H + ROW_GAP), rot: -0.7, delay: 11 },
  { x: GRID_LEFT + 3 * (CARD_W + COL_GAP), y: GRID_TOP + 2 * (CARD_H + ROW_GAP), rot: 0.9, delay: 4 },
];

interface ThumbnailCardProps {
  data: (typeof THUMBNAILS)[number];
  layout: (typeof THUMB_LAYOUT)[number];
}

const ThumbnailCard: React.FC<ThumbnailCardProps> = ({ data, layout }) => {
  const frame = useCurrentFrame();
  const { fps: videoFps } = useVideoConfig();

  const enterProgress = spring({
    frame,
    fps: videoFps,
    delay: layout.delay,
    config: { damping: 180, stiffness: 280 },
  });

  const wobble = interpolate(
    Math.sin((frame * 0.04 + layout.delay * 0.3) * Math.PI),
    [-1, 1],
    [-0.25, 0.25]
  );

  const opacity = interpolate(enterProgress, [0, 1], [0, 1]);
  const scale = interpolate(enterProgress, [0, 1], [0.4, 1]);
  const translateY = interpolate(enterProgress, [0, 1], [100, 0]);

  const imgH = CARD_H * 0.615;
  const infoH = CARD_H - imgH;

  return (
    <div
      style={{
        position: "absolute",
        left: layout.x,
        top: layout.y,
        width: CARD_W,
        height: CARD_H,
        opacity,
        transform: `scale(${scale}) translateY(${translateY}px) rotate(${layout.rot + wobble}deg)`,
        transformOrigin: "center center",
        filter: "drop-shadow(0px 16px 36px rgba(0,0,0,0.22))",
        borderRadius: 16,
        overflow: "hidden",
      }}
    >
      {/* Thumbnail image area */}
      <div
        style={{
          width: "100%",
          height: imgH,
          background: data.gradient,
          position: "relative",
          overflow: "hidden",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        <div
          style={{
            fontSize: 130,
            filter: "drop-shadow(0 8px 16px rgba(0,0,0,0.4))",
            userSelect: "none",
          }}
        >
          {data.emoji}
        </div>

        {/* Duration badge */}
        <div
          style={{
            position: "absolute",
            bottom: 12,
            right: 12,
            backgroundColor: "rgba(0,0,0,0.85)",
            color: COLORS.white,
            fontFamily: "'Inter', sans-serif",
            fontSize: 24,
            fontWeight: 700,
            padding: "5px 12px",
            borderRadius: 6,
          }}
        >
          {data.duration}
        </div>
      </div>

      {/* Info area */}
      <div
        style={{
          backgroundColor: COLORS.white,
          padding: "18px 20px 14px 20px",
          height: infoH,
          display: "flex",
          flexDirection: "column",
          justifyContent: "space-between",
          overflow: "hidden",
        }}
      >
        {/* Title */}
        <div
          style={{
            fontSize: 26,
            fontWeight: 700,
            color: "#0F0F0F",
            fontFamily: "'Inter', sans-serif",
            lineHeight: 1.3,
            display: "-webkit-box",
            WebkitLineClamp: 2,
            WebkitBoxOrient: "vertical",
            overflow: "hidden",
          }}
        >
          {data.title}
        </div>

        {/* Channel + meta */}
        <div style={{ display: "flex", flexDirection: "column", gap: 4 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
            {/* Channel avatar */}
            <div
              style={{
                width: 32,
                height: 32,
                borderRadius: "50%",
                background: data.accentColor,
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                fontSize: 15,
                fontWeight: 800,
                color: COLORS.white,
                fontFamily: "'Inter', sans-serif",
                flexShrink: 0,
              }}
            >
              {data.channel[0]}
            </div>
            <span
              style={{
                fontSize: 22,
                fontWeight: 600,
                color: "#606060",
                fontFamily: "'Inter', sans-serif",
              }}
            >
              {data.channel}
            </span>
            {data.verified && (
              <svg width={18} height={18} viewBox="0 0 24 24" fill="#606060">
                <path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm-2 14.5l-4-4 1.41-1.41L10 13.67l6.59-6.59L18 8.5l-8 8z" />
              </svg>
            )}
          </div>
          {/* Views with eye emoji + time ago */}
          <div
            style={{
              fontSize: 20,
              color: "#606060",
              fontFamily: "'Inter', sans-serif",
              display: "flex",
              alignItems: "center",
              gap: 6,
            }}
          >
            <span>👁️</span>
            <span>{data.views} · {data.timeAgo}</span>
          </div>
        </div>
      </div>
    </div>
  );
};

