      {THUMBNAILS.map((thumb, i) => {
        const layout = THUMB_LAYOUT[i % THUMB_LAYOUT.length];
        return <ThumbnailCard key={thumb.id} data={thumb} layout={layout} />;
      })}
    </AbsoluteFill>
  );
};

